def tune_proposal(log_posterior, theta_init, widths, scale, n_iterations=2000, burn_in=500):
    """Return the proposal covariance: the covariance of a pilot chain, times the factor scale."""

    # Pilot chain with a diagonal covariance from the guessed widths
    pilot, _ = metropolis(log_posterior, theta_init, np.diag(np.square(widths)), n_iterations)

    # Covariance of the pilot samples after the burn-in (np.atleast_2d keeps a matrix for one parameter)
    return scale * np.atleast_2d(np.cov(pilot[burn_in:].T))

def summarize(chain, names, burn_in):
    """Print the posterior mean and standard deviation of every parameter after the burn-in."""
    for j, name in enumerate(names):
        print(f"{name:<6} mean {chain[burn_in:, j].mean():.3f}, sd {chain[burn_in:, j].std():.3f}")

def corner_plot(samples, labels, truths, figsize):
    """Plot the posterior of each parameter on the diagonal and of each pair of parameters below it."""
    d = samples.shape[1]
    fig, axes = plt.subplots(d, d, figsize=figsize)

    for i in range(d):
        for j in range(d):
            ax = axes[i, j]

            # Leave the panels above the diagonal empty
            if j > i:
                ax.axis('off')
                continue

            # Histogram on the diagonal, density of the pairs below it, and the true values in red
            if i == j:
                ax.hist(samples[:, i], bins=40,
                        histtype='stepfilled', facecolor=('C0', 0.35), edgecolor='C0', linewidth=1.5)
                ax.axvline(truths[i], color='C3', linestyle='--')
                ax.set_yticks([])
            else:
                ax.hist2d(samples[:, j], samples[:, i], bins=40, cmap='book_blue')
                ax.axvline(truths[j], color='C3', linestyle='--', linewidth=1)
                ax.axhline(truths[i], color='C3', linestyle='--', linewidth=1)

            # Axis labels only on the outer panels
            if i < d - 1:
                ax.set_xticklabels([])
            else:
                ax.set_xlabel(labels[j])
            if j == 0 and i > 0:
                ax.set_ylabel(labels[i])
            elif j > 0 and i != j:
                ax.set_yticklabels([])

    plt.tight_layout()
    plt.show()

def log_posterior_mix(theta):
    """Return the log posterior of the power law and binary parameters, up to a constant."""
    alpha, mu_b, sigma_b, f = theta

    # The uniform priors are zero outside their ranges
    if not (0 < alpha < 5 and 0 < mu_b < 2 and 0 < sigma_b < 1 and 0 < f < 0.5):
        return -np.inf

    # Likelihood of each component, by importance sampling for the power law and in closed form for the Gaussian
    likelihood_pl = power_law_likelihood(alpha, Z_mix, ln_draws_mix)
    likelihood_binary = norm.pdf(x_mix, mu_b, np.sqrt(sigma_b**2 + sigma_mix**2))

    return np.sum(np.log((1 - f) * likelihood_pl + f * likelihood_binary))
